import test from 'ava';
import pLimit, {limitFunction} from './index.js';

const tick = () => new Promise(resolve => setTimeout(resolve, 0));

test('onIdle resolves immediately when already idle', async t => {
	const limit = pLimit(1);
	await limit.onIdle();
	t.pass();
});

test('onIdle resolves after active work completes', async t => {
	const limit = pLimit(1);
	let done = false;
	limit.onIdle().then(() => {
		done = true;
	}); // eslint-disable-line promise/prefer-await-to-then

	limit(async () => {
		await tick();
	});

	t.false(done);
	await limit.onIdle();
	t.true(done);
});

test('onIdle waits for the waiting queue to drain', async t => {
	const limit = pLimit(1);
	for (let index = 0; index < 5; index++) {
		limit(async () => {
			await tick();
		});
	}

	t.is(limit.pendingCount + limit.activeCount, 5);
	await limit.onIdle();
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('multiple onIdle waiters all resolve', async t => {
	const limit = pLimit(2);
	const order = [];
	const waiters = [
		limit.onIdle().then(() => order.push(0)), // eslint-disable-line promise/prefer-await-to-then
		limit.onIdle().then(() => order.push(1)), // eslint-disable-line promise/prefer-await-to-then
		limit.onIdle().then(() => order.push(2)), // eslint-disable-line promise/prefer-await-to-then
	];

	limit(async () => {
		await tick();
	});

	await Promise.all(waiters);
	t.deepEqual(order.sort(), [0, 1, 2]);
});

test('onIdle resolves when jobs reject', async t => {
	const limit = pLimit(2);
	const promises = [
		limit(async () => {
			await tick();
			throw new Error('boom');
		}),
		limit(async () => {
			throw new Error('bang');
		}),
		limit(async () => tick()),
	];

	await limit.onIdle();
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await t.throwsAsync(Promise.allSettled(promises).then(results => results.find(result => result.status === 'rejected').reason));
});

test('onIdle counts reserved slots as active', async t => {
	const limit = pLimit({concurrency: 3, rejectOnClear: false});
	t.is(limit.concurrency, 3);

	const promise = limit(async () => {
		await tick();
	});

	t.is(limit.activeCount, 1);
	let resolved = false;
	limit.onIdle().then(() => {
		resolved = true;
	}); // eslint-disable-line promise/prefer-await-to-then

	await tick();
	t.false(resolved);
	await promise;
	await limit.onIdle();
	t.true(resolved);
});

test('onIdle does not report idle early when a job enqueues another job', async t => {
	const limit = pLimit(1);
	let secondStarted = false;

	limit(async () => {
		await tick();
		limit(async () => {
			secondStarted = true;
			await tick();
		});
	});

	await limit.onIdle();
	t.true(secondStarted, 'follow-up task enqueued from a .then() continuation must keep the limiter non-idle');
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('clearQueue releases onIdle waiters with rejectOnClear false and unresolved discarded promises', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: false});
	const discarded = [];

	discarded.push(limit(async () => tick())); // Runs first, keeps limiter busy.
	discarded.push(limit(async () => tick())); // Queued, will be discarded.
	discarded.push(limit(async () => tick())); // Queued, will be discarded.

	let idleResolved = false;
	const idle = limit.onIdle().then(() => {
		idleResolved = true;
	}); // eslint-disable-line promise/prefer-await-to-then

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await idle;
	t.true(idleResolved);
	t.is(limit.activeCount, 0);

	// The discarded promises stay unresolved by design; detach them.
	void Promise.allSettled;
});

test('clearQueue releases onIdle waiters with rejectOnClear true', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: true});
	const promises = [limit(async () => tick()), limit(async () => tick())];

	const idle = limit.onIdle();
	limit.clearQueue();
	await idle;
	t.is(limit.pendingCount, 0);

	const results = await Promise.allSettled(promises.slice(1));
	t.is(results[0].status, 'rejected');
	await promises[0];
});

test('limitFunction wrapper exposes onIdle', async t => {
	let release;
	const gate = new Promise(resolve => {
		release = resolve;
	});

	const limited = limitFunction(async () => {
		await gate;
	}, {concurrency: 1});

	const promises = [limited(), limited(), limited()];
	await tick();

	let resolved = false;
	limited.onIdle().then(() => {
		resolved = true;
	}); // eslint-disable-line promise/prefer-await-to-then

	await tick();
	t.false(resolved);

	release();
	await limited.onIdle();
	t.true(resolved);
	await Promise.all(promises);
});

test('limitFunction onIdle resolves immediately when already idle', async t => {
	const limited = limitFunction(async () => {}, {concurrency: 2});
	await limited.onIdle();
	t.pass();
});

test('onIdle preserves FIFO ordering of queued tasks', async t => {
	const limit = pLimit(1);
	const order = [];
	for (let index = 0; index < 6; index++) {
		limit(async () => {
			await tick();
			order.push(index);
		});
	}

	await limit.onIdle();
	t.deepEqual(order, [0, 1, 2, 3, 4, 5]);
});

test('onIdle reflects concurrency changes', async t => {
	const limit = pLimit(1);
	limit(async () => {
		await tick();
	});
	limit(async () => {
		await tick();
	});
	limit(async () => {
		await tick();
	});

	limit.concurrency = 3;
	await limit.onIdle();
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

